# Analyze character mappings by position
print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input {i} ({inp}) -> Output {i} ({out})")

    # Show what characters are added/changed
    if len(inp) < len(out):
        print(f"  Length increased from {len(inp)} to {len(out)}")
        # Find inserted characters
        j = 0
        for char_out in out:
            if j < len(inp) and inp[j] == char_out:
                print(f"  Position {j}: '{char_out}' unchanged")
                j += 1
            else:
                print(f"  Inserted: '{char_out}' at position {j}")
                j += 1
    elif len(inp) > len(out):
        print(f"  Length decreased from {len(inp)} to {len(out)}")
    else:
        print(f"  Same length")
